"""EPIC protocol laboratory: replay / audit / export.

Standard library only.  Reads UTF-8 JSON Lines from stdin, writes one JSON
object per input line.
"""
import sys
import json
import math
from collections import deque

# ---------------------------------------------------------------------------
# Errors
# ---------------------------------------------------------------------------
class Err(Exception):
    def __init__(self, code):
        self.code = code
        super().__init__(code)

def schema():
    raise Err("E_SCHEMA")

def limit():
    raise Err("E_LIMIT")

def e_json():
    raise Err("E_JSON")

# ---------------------------------------------------------------------------
# JSON parsing (strict)
# ---------------------------------------------------------------------------
class _JP(Exception):
    pass

def _reject_const(_):
    raise _JP()

def _float(s):
    f = float(s)
    if not math.isfinite(f):
        raise _JP()
    return f

def _pairs(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise _JP()
        d[k] = v
    return d

def parse_json(text):
    try:
        return json.loads(text, object_pairs_hook=_pairs,
                          parse_constant=_reject_const, parse_float=_float)
    except _JP:
        e_json()
    except (json.JSONDecodeError, ValueError, RecursionError):
        e_json()

# ---------------------------------------------------------------------------
# Type helpers
# ---------------------------------------------------------------------------
def is_int(x):
    return type(x) is int

def is_num(x):
    return type(x) is int

# ---------------------------------------------------------------------------
# Inputs validation  (P x R x D)
# ---------------------------------------------------------------------------
IN_LO = -1000000000
IN_HI = 1000000000

def validate_inputs(v):
    if not isinstance(v, list):
        schema()
    P = len(v)
    if P < 1 or P > 8:
        limit()
    for r in range(P):
        if not isinstance(v[r], list):
            schema()
    R = len(v[0])
    if R > 128:
        limit()
    for r in range(P):
        if len(v[r]) != R:
            schema()
    if R == 0:
        return v, P, R, 0
    for r in range(P):
        for q in range(R):
            if not isinstance(v[r][q], list):
                schema()
    D = len(v[0][0])
    if D > 32:
        limit()
    for r in range(P):
        for q in range(R):
            vec = v[r][q]
            if len(vec) != D:
                schema()
            for x in vec:
                if not is_int(x):
                    schema()
                if x < IN_LO or x > IN_HI:
                    limit()
    return v, P, R, D

# ---------------------------------------------------------------------------
# Name validation
# ---------------------------------------------------------------------------
import re
_NAME_RE = re.compile(r"^[A-Za-z][A-Za-z0-9_]{0,63}$")

def validate_name(n):
    if not isinstance(n, str):
        schema()
    if len(n) > 64:
        limit()
    try:
        n.encode("ascii")
    except UnicodeEncodeError:
        schema()
    if not _NAME_RE.match(n):
        schema()
    return n

# ---------------------------------------------------------------------------
# Replay
# ---------------------------------------------------------------------------
def do_replay(req, inputs, P, R, D):
    slots = req["slots"]
    window = req["window"]
    events = req["events"]
    if not is_int(slots):
        schema()
    if slots < 1 or slots > 16:
        limit()
    if not is_int(window):
        schema()
    if window < 1 or window > slots:
        limit()
    if not isinstance(events, list):
        schema()
    if len(events) > 20000:
        limit()

    # validate & normalise events
    norm = []
    for ev in events:
        if not isinstance(ev, list):
            schema()
        if len(ev) < 1:
            schema()
        act = ev[0]
        if not isinstance(act, str):
            schema()
        if act == "send":
            if len(ev) != 3:
                schema()
            rank = ev[1]; q = ev[2]
            if not is_int(rank) or not is_int(q):
                schema()
            if rank < 0 or rank >= P:
                limit()
            if q < 0 or q >= R:
                limit()
            norm.append(("send", rank, q))
        elif act == "retry":
            if len(ev) != 2:
                schema()
            rank = ev[1]
            if not is_int(rank):
                schema()
            if rank < 0 or rank >= P:
                limit()
            norm.append(("retry", rank))
        elif act in ("deliver", "drop", "duplicate"):
            if len(ev) != 2:
                schema()
            pid = ev[1]
            if not is_int(pid):
                schema()
            if pid < 0 or pid > 200000:
                limit()
            norm.append((act, pid))
        else:
            schema()

    # ---- simulation state ----
    sent = [0] * P
    received = [[] for _ in range(P)]
    up_next = [0] * P
    acked = [0] * P
    floor = 0
    # buffer: seq -> {ranks:set, sum:list}
    buffer = {}
    pending = {}          # id -> packet dict
    next_id = 0
    total_created = 0

    def new_packet(kind, rank, seq, value):
        nonlocal next_id, total_created
        pid = next_id
        next_id += 1
        total_created += 1
        if total_created > 200000:
            limit()
        pending[pid] = {"id": pid, "kind": kind, "rank": rank,
                        "seq": seq, "value": value}
        if len(pending) > 2048:
            limit()
        return pid

    event_results = []

    for ev in norm:
        act = ev[0]
        created = []
        status = "ok"
        if act == "send":
            rank = ev[1]; q = ev[2]
            if sent[rank] <= q < min(R, sent[rank] + window):
                val = inputs[rank][q]
                created.append(new_packet("up", rank, q, val))
            else:
                status = "disabled"
        elif act == "retry":
            rank = ev[1]
            for q in sorted(buffer.keys()):
                e = buffer[q]
                if q >= acked[rank] and len(e["ranks"]) == P:
                    created.append(new_packet("down", rank, q, list(e["sum"])))
        else:
            pid = ev[1]
            if pid not in pending:
                status = "missing"
            else:
                pkt = pending.pop(pid)
                if act == "drop":
                    pass
                elif act == "duplicate":
                    created.append(new_packet(pkt["kind"], pkt["rank"],
                                              pkt["seq"], pkt["value"]))
                else:  # deliver
                    kind = pkt["kind"]
                    if kind == "up":
                        r = pkt["rank"]; q = pkt["seq"]; val = pkt["value"]
                        if floor <= q < floor + slots:
                            e = buffer.get(q)
                            if e is None:
                                e = {"ranks": set(), "sum": [0] * D}
                                buffer[q] = e
                            newly = False
                            if r not in e["ranks"]:
                                e["ranks"].add(r)
                                s = e["sum"]
                                for i in range(D):
                                    s[i] += val[i]
                                newly = True
                            # advance up_next
                            k = up_next[r]
                            while True:
                                ee = buffer.get(up_next[r])
                                if ee is not None and r in ee["ranks"]:
                                    up_next[r] += 1
                                else:
                                    break
                            created.append(new_packet("uack", r, up_next[r], None))
                            if newly and len(e["ranks"]) == P:
                                for rr in range(P):
                                    created.append(new_packet("down", rr, q,
                                                              list(e["sum"])))
                        else:
                            created.append(new_packet("uack", r, up_next[r], None))
                    elif kind == "uack":
                        r = pkt["rank"]; k = pkt["seq"]
                        if k > sent[r]:
                            sent[r] = k
                    elif kind == "down":
                        r = pkt["rank"]; q = pkt["seq"]; val = pkt["value"]
                        if q == len(received[r]):
                            received[r].append(val)
                        created.append(new_packet("dack", r, len(received[r]), None))
                    elif kind == "dack":
                        r = pkt["rank"]; k = pkt["seq"]
                        if k > acked[r]:
                            acked[r] = k
                        floor = min(acked)
                        for q in list(buffer.keys()):
                            if q < floor:
                                del buffer[q]
        event_results.append({"status": status, "created": created})

    hosts = [{"sent": sent[r], "received": received[r]} for r in range(P)]
    slots_out = []
    for q in sorted(buffer.keys()):
        e = buffer[q]
        slots_out.append({"seq": q, "ranks": sorted(e["ranks"]),
                          "sum": e["sum"]})
    packets_out = [pending[pid] for pid in sorted(pending.keys())]
    return {"hosts": hosts, "floor": floor, "slots": slots_out,
            "packets": packets_out, "events": event_results}

# ---------------------------------------------------------------------------
# Graph (audit / export) validation
# ---------------------------------------------------------------------------
SNAP_LO = -(1 << 60)
SNAP_HI = (1 << 60)

def check_vec(v, D):
    if not isinstance(v, list):
        schema()
    if len(v) != D:
        schema()
    for x in v:
        if not is_int(x):
            schema()
        if x < SNAP_LO or x > SNAP_HI:
            limit()

def validate_graph(req, inputs, P, R, D):
    states = req["states"]
    edges = req["edges"]
    start = req["start"]
    fairness = req["fairness"]

    if not isinstance(states, list):
        schema()
    if len(states) < 1 or len(states) > 12000:
        limit()
    if not isinstance(edges, list):
        schema()
    if len(edges) > 60000:
        limit()
    if not is_int(start):
        schema()
    if start < 0 or start >= len(states):
        limit()
    if not isinstance(fairness, list):
        schema()
    if len(fairness) > 16:
        limit()

    n = len(states)
    # states
    for st in states:
        if not isinstance(st, dict):
            schema()
        if set(st.keys()) != {"delivered", "slots"}:
            schema()
        delivered = st["delivered"]
        if not isinstance(delivered, list) or len(delivered) != P:
            schema()
        for r in range(P):
            lst = delivered[r]
            if not isinstance(lst, list):
                schema()
            if len(lst) > R:
                limit()
            for vec in lst:
                check_vec(vec, D)
        sl = st["slots"]
        if not isinstance(sl, list):
            schema()
        if len(sl) > 16:
            limit()
        seen_seq = set()
        for s in sl:
            if not isinstance(s, dict):
                schema()
            if set(s.keys()) != {"seq", "ranks", "sum"}:
                schema()
            seq = s["seq"]
            if not is_int(seq):
                schema()
            if seq < 0 or seq >= R:
                limit()
            if seq in seen_seq:
                schema()
            seen_seq.add(seq)
            ranks = s["ranks"]
            if not isinstance(ranks, list):
                schema()
            seen_r = set()
            for rr in ranks:
                if not is_int(rr):
                    schema()
                if rr < 0 or rr >= P:
                    limit()
                if rr in seen_r:
                    schema()
                seen_r.add(rr)
            check_vec(s["sum"], D)

    # edges
    edge_names = set()
    seen_triples = set()
    for e in edges:
        if not isinstance(e, list) or len(e) != 3:
            schema()
        src, name, tgt = e
        if not is_int(src) or not is_int(tgt):
            schema()
        if src < 0 or src >= n or tgt < 0 or tgt >= n:
            limit()
        validate_name(name)
        triple = (src, name, tgt)
        if triple in seen_triples:
            schema()
        seen_triples.add(triple)
        edge_names.add(name)

    # fairness
    fair_names = set()
    fair_norm = []
    for f in fairness:
        if not isinstance(f, dict):
            schema()
        if set(f.keys()) != {"action", "mode"}:
            schema()
        name = validate_name(f["action"])
        mode = f["mode"]
        if mode not in ("weak", "strong") or not isinstance(mode, str):
            schema()
        if name in fair_names:
            schema()
        fair_names.add(name)
        fair_norm.append((name, mode))

    all_names = edge_names | fair_names
    if len(all_names) > 64:
        limit()

    return states, edges, start, fair_norm, all_names

# ---------------------------------------------------------------------------
# Predicates
# ---------------------------------------------------------------------------
def build_expected(inputs, P, R, D):
    expected = []
    for q in range(R):
        vec = [0] * D
        for r in range(P):
            iv = inputs[r][q]
            for i in range(D):
                vec[i] += iv[i]
        expected.append(vec)
    return expected

def state_safe(st, inputs, P, R, D, expected):
    delivered = st["delivered"]
    for r in range(P):
        lst = delivered[r]
        for q in range(len(lst)):
            if lst[q] != expected[q]:
                return False
    for s in st["slots"]:
        q = s["seq"]
        acc = [0] * D
        for rr in s["ranks"]:
            iv = inputs[rr][q]
            for i in range(D):
                acc[i] += iv[i]
        if acc != s["sum"]:
            return False
    return True

def state_done(st, P, R):
    for r in range(P):
        if len(st["delivered"][r]) != R:
            return False
    return True

# ---------------------------------------------------------------------------
# Audit
# ---------------------------------------------------------------------------
def do_audit(req, inputs, P, R, D):
    states, edges, start, fair_norm, all_names = validate_graph(req, inputs, P, R, D)
    n = len(states)
    expected = build_expected(inputs, P, R, D)

    safe_flags = [state_safe(st, inputs, P, R, D, expected) for st in states]
    done_flags = [state_done(st, P, R) for st in states]

    # adjacency
    succ = [[] for _ in range(n)]      # list of (tgt, eid, action)
    for eid, e in enumerate(edges):
        src, name, tgt = e
        succ[src].append((tgt, eid, name))

    # ---- safety reachability ----
    parent = {start: None}
    dq = deque([start])
    safe = True
    safety_witness = None
    if not safe_flags[start]:
        safe = False
        safety_witness = []
    else:
        while dq:
            s = dq.popleft()
            for (tgt, eid, name) in succ[s]:
                if tgt not in parent:
                    parent[tgt] = (s, eid)
                    if not safe_flags[tgt]:
                        # reconstruct
                        path = []
                        cur = tgt
                        while parent[cur] is not None:
                            ps, pe = parent[cur]
                            path.append(pe)
                            cur = ps
                        path.reverse()
                        safe = False
                        safety_witness = path
                        dq.clear()
                        break
                    dq.append(tgt)
            else:
                continue
            break

    # ---- termination ----
    terminates, liveness = compute_termination(
        states, succ, start, done_flags, fair_norm, n)

    return {"safe": safe,
            "safety": None if safe else {"prefix": safety_witness},
            "terminates": terminates,
            "liveness": None if terminates else liveness}

# ---------------------------------------------------------------------------
# Termination analysis
# ---------------------------------------------------------------------------
def sccs_of(nodes_set, succ, pred):
    """Kosaraju SCCs of induced subgraph on nodes_set (iterative)."""
    nodes = list(nodes_set)
    nodeset = nodes_set
    visited = set()
    order = []
    for s0 in nodes:
        if s0 in visited:
            continue
        visited.add(s0)
        stack = [s0]
        idx_stack = [0]
        while stack:
            s = stack[-1]
            succs = succ[s]
            i = idx_stack[-1]
            found = False
            while i < len(succs):
                v = succs[i][0]
                i += 1
                if v in nodeset and v not in visited:
                    idx_stack[-1] = i
                    visited.add(v)
                    stack.append(v)
                    idx_stack.append(0)
                    found = True
                    break
            if not found:
                idx_stack[-1] = i
                order.append(s)
                stack.pop()
                idx_stack.pop()
    visited2 = set()
    comps = []
    for s0 in reversed(order):
        if s0 in visited2:
            continue
        comp = set()
        visited2.add(s0)
        st = [s0]
        while st:
            s = st.pop()
            comp.add(s)
            for (u, eid, name) in pred[s]:
                if u in nodeset and u not in visited2:
                    visited2.add(u)
                    st.append(u)
        comps.append(comp)
    return comps


def compute_termination(states, succ, start, done_flags, fair_norm, n):
    if done_flags[start]:
        return True, None

    # Build pred lists for graph (all explicit edges)
    pred = [[] for _ in range(n)]
    for s in range(n):
        for (tgt, eid, name) in succ[s]:
            pred[tgt].append((s, eid, name))

    # N = non-done states reachable from start staying in non-done
    N = set([start])
    parentN = {start: None}
    dq = deque([start])
    while dq:
        s = dq.popleft()
        for (tgt, eid, name) in succ[s]:
            if done_flags[tgt]:
                continue
            if tgt not in N:
                N.add(tgt)
                parentN[tgt] = (s, eid)
                dq.append(tgt)

    # fairness splits
    weak_actions = []
    strong_actions = []
    for (name, mode) in fair_norm:
        if mode == "weak":
            weak_actions.append(name)
        else:
            strong_actions.append(name)

    # enabled-state sets per fairness action (global explicit edges)
    en_states = {}
    edges_by_action = {}
    for a in set(weak_actions) | set(strong_actions):
        en_states[a] = set()
        edges_by_action[a] = []
    for s in range(n):
        for (tgt, eid, name) in succ[s]:
            if name in en_states:
                en_states[name].add(s)
                edges_by_action[name].append((s, tgt, eid))

    # dedupe action lists (fairness unique already), keep order
    seen = set()
    wa = []
    for a in weak_actions:
        if a not in seen:
            wa.append(a); seen.add(a)
    seen = set()
    sa = []
    for a in strong_actions:
        if a not in seen:
            sa.append(a); seen.add(a)
    weak_actions, strong_actions = wa, sa

    def internal_edge(S, a):
        for (u, v, eid) in edges_by_action.get(a, ()):
            if u in S and v in S:
                return (u, v, eid)
        return None

    def find_fair(S):
        # find problematic strong action
        for a in strong_actions:
            es = en_states[a]
            # does any state in S enable a?
            enabled_in_S = False
            for s in S:
                if s in es:
                    enabled_in_S = True
                    break
            if enabled_in_S:
                if internal_edge(S, a) is None:
                    newS = S - es
                    if not newS:
                        return None
                    for C in sccs_of(newS, succ, pred):
                        r = find_fair(C)
                        if r is not None:
                            return r
                    return None
        # weak check
        for a in weak_actions:
            es = en_states[a]
            if S <= es:
                if internal_edge(S, a) is None:
                    return None
        return set(S)

    # Try each base SCC
    base_comps = sccs_of(N, succ, pred)
    for C in base_comps:
        S = find_fair(set(C))
        if S is not None:
            # construct loop & prefix
            loop = build_loop(S, weak_actions, strong_actions, en_states,
                              edges_by_action, internal_edge, succ, pred)
            prefix = build_prefix(start, next(iter(S)), parentN)
            return False, {"prefix": prefix, "loop": loop}
    return True, None


def build_prefix(start, target, parentN):
    path = []
    cur = target
    while parentN[cur] is not None:
        ps, eid = parentN[cur]
        path.append(eid)
        cur = ps
    path.reverse()
    return path


def _bfs_paths(root, S, adj, want_fwd):
    """BFS within S.  If want_fwd: adjacency edges (u->v) produce parent
    path root->v.  Else adjacency is reverse (v->u represents forward u->v);
    returns for each v a list of forward edges v->...->root."""
    parent_edge = {root: None}
    parent_node = {root: None}
    dq = deque([root])
    while dq:
        u = dq.popleft()
        for item in adj[u]:
            # item: (nbr, edgeid)
            v, eid = item
            if v in S and v not in parent_edge:
                parent_edge[v] = eid
                parent_node[v] = u
                dq.append(v)
    return parent_edge, parent_node


def build_loop(S, weak_actions, strong_actions, en_states,
               edges_by_action, internal_edge, succ, pred):
    required = []
    for a in strong_actions:
        es = en_states[a]
        if any(s in es for s in S):
            e = internal_edge(S, a)
            if e is not None:
                required.append(e)
    witnesses = []
    for a in weak_actions:
        es = en_states[a]
        if S <= es:
            e = internal_edge(S, a)
            if e is not None:
                required.append(e)
        else:
            w = None
            for s in S:
                if s not in es:
                    w = s
                    break
            if w is not None:
                witnesses.append(w)

    # choose root
    targets = set(witnesses)
    for (u, v, eid) in required:
        targets.add(u); targets.add(v)
    if targets:
        root = next(iter(targets))
    else:
        root = next(iter(S))

    # forward adjacency within graph (target, eid)
    fadj = [[] for _ in range(len(succ))]
    radj = [[] for _ in range(len(pred))]
    for s in range(len(succ)):
        for (tgt, eid, name) in succ[s]:
            fadj[s].append((tgt, eid))
            radj[tgt].append((s, eid))

    fpe, fpn = _bfs_paths(root, S, fadj, True)
    rpe, rpn = _bfs_paths(root, S, radj, False)

    def path_fwd(target):
        # root -> target edges
        if target == root:
            return []
        out = []
        cur = target
        while cur != root:
            eid = fpe[cur]
            out.append(eid)
            cur = fpn[cur]
        out.reverse()
        return out

    def path_back(target):
        # target -> root edges
        if target == root:
            return []
        out = []
        cur = target
        while cur != root:
            eid = rpe[cur]
            out.append(eid)
            cur = rpn[cur]
        return out

    walk = []
    for (u, v, eid) in required:
        walk.extend(path_fwd(u))
        walk.append(eid)
        walk.extend(path_back(v))
    for w in witnesses:
        walk.extend(path_fwd(w))
        walk.extend(path_back(w))

    if not walk:
        walk = [-1]
    return walk

# ---------------------------------------------------------------------------
# Export
# ---------------------------------------------------------------------------
def do_export(req, inputs, P, R, D):
    states, edges, start, fair_norm, all_names = validate_graph(req, inputs, P, R, D)
    n = len(states)
    expected = build_expected(inputs, P, R, D)
    safe_flags = [state_safe(st, inputs, P, R, D, expected) for st in states]
    done_flags = [state_done(st, P, R) for st in states]

    action_names = sorted(all_names)
    index = {name: i + 1 for i, name in enumerate(action_names)}

    def fmt_set(items):
        if not items:
            return "{}"
        return "{" + ", ".join(items) + "}"

    edges_items = ["<<%d,%d,%d>>" % (e[0], index[e[1]], e[2]) for e in edges]
    edges_str = fmt_set(edges_items)

    if action_names:
        an_str = "<<" + ", ".join(action_names) + ">>"
    else:
        an_str = "<<>>"

    wf = [str(index[name]) for (name, mode) in fair_norm if mode == "weak"]
    sf = [str(index[name]) for (name, mode) in fair_norm if mode == "strong"]
    wf_str = fmt_set(wf)
    sf_str = fmt_set(sf)

    safe_items = [str(i) for i in range(n) if safe_flags[i]]
    done_items = [str(i) for i in range(n) if done_flags[i]]
    safe_str = fmt_set(safe_items)
    done_str = fmt_set(done_items)

    lines = [
        "---- MODULE ModelData ----",
        "EXTENDS Integers, Sequences, FiniteSets",
        "Nodes == 0..%d" % (n - 1),
        "Initial == %d" % start,
        "Edges == %s" % edges_str,
        "ActionNames == %s" % an_str,
        "WFIds == %s" % wf_str,
        "SFIds == %s" % sf_str,
        "SafeNodes == %s" % safe_str,
        "DoneNodes == %s" % done_str,
        "====",
    ]
    module = "\n".join(lines)
    config = ("SPECIFICATION Spec\n"
              "INVARIANT Safety\n"
              "PROPERTY Termination\n"
              "CHECK_DEADLOCK FALSE")
    return {"module": module, "config": config}

# ---------------------------------------------------------------------------
# Dispatch
# ---------------------------------------------------------------------------
def dispatch(obj):
    if not isinstance(obj, dict):
        schema()
    if "op" not in obj or "inputs" not in obj:
        schema()
    op = obj["op"]
    if not isinstance(op, str):
        schema()

    if op == "replay":
        expected_keys = {"op", "inputs", "slots", "window", "events"}
    elif op in ("audit", "export"):
        expected_keys = {"op", "inputs", "states", "edges", "start", "fairness"}
    else:
        schema()
    if set(obj.keys()) != expected_keys:
        schema()

    inputs, P, R, D = validate_inputs(obj["inputs"])

    if op == "replay":
        return do_replay(obj, inputs, P, R, D)
    elif op == "audit":
        return do_audit(obj, inputs, P, R, D)
    else:
        return do_export(obj, inputs, P, R, D)

# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    data = sys.stdin.buffer.read()
    lines = data.split(b"\n")
    if lines and lines[-1] == b"":
        lines.pop()

    out = sys.stdout
    for raw in lines:
        if len(raw) > 32 * 1024 * 1024:
            out.write('{"error":"E_LIMIT"}\n')
            continue
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            out.write('{"error":"E_JSON"}\n')
            continue
        try:
            obj = parse_json(text)
        except Err as e:
            out.write(json.dumps({"error": e.code}) + "\n")
            continue
        try:
            result = dispatch(obj)
            out.write(json.dumps(result, separators=(",", ":")) + "\n")
        except Err as e:
            out.write(json.dumps({"error": e.code}) + "\n")
        except Exception:
            out.write('{"error":"E_SCHEMA"}\n')


if __name__ == "__main__":
    main()
