class LIM(Exception): pass

def ref_replay(req):
    inputs=req["inputs"]; P=len(inputs); R=len(inputs[0]) if P else 0; D=len(inputs[0][0]) if R else 0
    slots=req["slots"]; window=req["window"]; events=req["events"]
    sent=[0]*P; received=[[] for _ in range(P)]; up_next=[0]*P; acked=[0]*P; floor=0
    # buffer list of physical slots
    buf=[None]*slots   # each None or dict(seq,ranks set,sum list)
    pending={}; nid=0; total=0
    def create(kind,rank,seq,value):
        nonlocal nid,total
        pid=nid; nid+=1; total+=1
        if total>200000: raise LIM()
        pending[pid]={"id":pid,"kind":kind,"rank":rank,"seq":seq,"value":value}
        if len(pending)>2048: raise LIM()
        return pid
    def find_entry(q):
        ph=q%slots
        e=buf[ph]
        if e is not None and e["seq"]==q: return e
        return None
    def make_entry(q):
        ph=q%slots
        e={"seq":q,"ranks":set(),"sum":[0]*D}
        buf[ph]=e
        return e
    evres=[]
    for ev in events:
        act=ev[0]; created=[]; status="ok"
        if act=="send":
            r=ev[1]; q=ev[2]
