    sl.sort(key=lambda e:e["seq"])
    slots_out=[{"seq":e["seq"],"ranks":sorted(e["ranks"]),"sum":e["sum"]} for e in sl]
    packets=[pending[i] for i in sorted(pending)]
    return {"hosts":hosts,"floor":floor,"slots":slots_out,"packets":packets,"events":evres}

