    exp_edges=set((e[0],idx[e[1]],e[2]) for e in edges)
    wf=set(idx[f["action"]] for f in fair if f["mode"]=="weak")
    sf=set(idx[f["action"]] for f in fair if f["mode"]=="strong")
    safeS=set(i for i in range(len(states)) if safe(states[i]))
    doneS=set(i for i in range(len(states)) if done(states[i]))
    return names,exp_edges,wf,sf,safeS,doneS,len(states),start

def parse_module(mod):
    lines=[l.strip() for l in mod.splitlines() if l.strip()]
    assert lines[0]=="---- MODULE ModelData ----", lines[0]
    assert lines[-1]=="====", lines[-1]
    assert lines[1]=="EXTENDS Integers, Sequences, FiniteSets"
    defs={}
    order=[]
    for l in lines[2:-1]:
        m=re.match(r"^(\w+) == (.+)$", l)
        assert m, l
        defs[m.group(1)]=m.group(2); order.append(m.group(1))
    assert order==["Nodes","Initial","Edges","ActionNames","WFIds","SFIds","SafeNodes","DoneNodes"], order
    return defs

def parse_set_triples(s):
    s=s.strip()
    assert s.startswith("{") and s.endswith("}")
    inner=s[1:-1].strip()
    if not inner: return set()
    parts=re.findall(r"<<\s*(-?\d+)\s*,\s*(-?\d+)\s*,\s*(-?\d+)\s*>>",inner)
    res=set((int(a),int(b),int(c)) for a,b,c in parts)
    # ensure nothing else
    return res

def parse_set_ints(s):
    s=s.strip(); assert s.startswith("{") and s.endswith("}")
    inner=s[1:-1].strip()
    if not inner: return set()
    return set(int(x) for x in inner.split(","))

def parse_tuple(s):
    s=s.strip(); assert s.startswith("<<") and s.endswith(">>")
    inner=s[2:-2].strip()
    if not inner: return []
    return [x.strip() for x in inner.split(",")]

