                    if k=="up":
                        r=pkt["rank"];q=pkt["seq"];val=pkt["value"]
                        if floor<=q<floor+slots:
                            e=fe(q)
                            if e is None:e=me(q)
                            newly=False
                            if r not in e["ranks"]:
                                e["ranks"].add(r)
                                for i in range(D):e["sum"][i]+=val[i]
                                newly=True
                            while True:
                                ee=fe(up_next[r])
                                if ee is not None and r in ee["ranks"]:up_next[r]+=1
                                else:break
                            created.append(create("uack",r,up_next[r],None))
