        out.append(v)
    return out,P,R,D
def is_safe(st,inputs,P,R,D,exp):
    for r in range(P):
        for q,vec in enumerate(st["delivered"][r]):
            if vec!=exp[q]:return False
    for s in st["slots"]:
        q=s["seq"];acc=[0]*D
        for rr in s["ranks"]:
            for i in range(D):acc[i]+=inputs[rr][q][i]
        if acc!=s["sum"]:return False
    return True
def is_done(st,P,R):
    return all(len(st["delivered"][r])==R for r in range(P))
def brute_term(inputs,states,edges,start,fair,P,R,D):
    n=len(states);done=[is_done(states[i],P,R) for i in range(n)]
    if done[start]:return True
    succ=[[] for _ in range(n)]
    for e in edges:succ[e[0]].append(e[2])
    N={start};dq=[start]
    while dq:
        s=dq.pop()
        for t in succ[s]:
            if done[t]:continue
            if t not in N:N.add(t);dq.append(t)
    weak=[a for a,m in fair if m=="weak"];strong=[a for a,m in fair if m=="strong"]
    ens={a:set() for a in set(weak)|set(strong)}
    for e in edges:
        if e[1] in ens:ens[e[1]].add(e[0])
    def has_int(S,a):
        return any(e[1]==a and e[0] in S and e[2] in S for e in edges)
    L=list(N)
    # precompute adjacency dicts restricted lazily
    for mask in range(1,1<<len(L)):
        S=set(L[i] for i in range(len(L)) if mask>>i&1)
        st0=next(iter(S))
        # reachability within S
        def reach(fwd):
            seen={st0};st=[st0]
            while st:
                u=st.pop()
                if fwd:
                    for e in edges:
                        if e[0]==u and e[2] in S and e[2] not in seen:seen.add(e[2]);st.append(e[2])
                else:
                    for e in edges:
                        if e[2]==u and e[0] in S and e[0] not in seen:seen.add(e[0]);st.append(e[0])
            return seen
        if reach(True)!=S or reach(False)!=S:continue
        ok=True
        for a in weak:
            if S<=ens[a] and not has_int(S,a):ok=False;break
        if not ok:continue
        for a in strong:
            if (S&ens[a]) and not has_int(S,a):ok=False;break
        if not ok:continue
        return False
    return True
